set local statement_timeout='15s';
do $repair$
declare affected integer;
begin
 if exists(select 1 from supabase_migrations.schema_migrations where version='__SOURCE_VERSION__') then raise exception 'RELEASE_MIGRATION_TARGET_ALREADY_EXISTS'; end if;
 update supabase_migrations.schema_migrations m set version='__SOURCE_VERSION__'
